MultiLanguageSpellData['mx'][99] = {name = "Rugido incapacitante", additional_info = "[q0]Talento\n{Instante} {30 seg de reutilización}\n[q]Adopta la forma de oso e invoca al espíritu de Ursol para proferir un rugido ensordecedor que incapacita a todos los enemigos en un radio de 10 m durante 3 s. El daño puede cancelar el efecto."}
