MultiLanguageSpellData['mx'][116] = {name = "Descarga de Escarcha", additional_info = "{2% del maná base} {Alcance de 40 m}\nHechizo de 2 seg\n[q]Lanza una descarga de escarcha al enemigo que inflige ([106.37% of Spell Power]) p. de daño de escarcha y reduce un 50% la velocidad de movimiento durante 8 s."}
MultiLanguageSpellData['mx'][118] = {name = "Polimorfia", additional_info = "{4% del maná base} {Alcance de 30 m}\nHechizo de 1.7 seg\n[q]Transforma al enemigo en una oveja que vaga sin dirección y queda incapacitada durante 1 min. Durante el efecto, la víctima no puede realizar ninguna acción, pero regenera salud con mucha rapidez. El daño puede cancelar el efecto. Límite: 1.\n\n Solo funciona en bestias, humanoides y alimañas. [ Glifo de Forma de alimaña : Cuando afecta a alimañas, puede afectar a varios objetivos y dura 1 día ]"}
MultiLanguageSpellData['mx'][120] = {name = "Cono de frío", additional_info = "4% del maná base\n{Instante} {12 seg de reutilización}\n[q]Los objetivos situados en un cono frente a ti reciben ([43.125% of Spell Power]) p. de daño de escarcha y sufren una ralentización del 70% durante 5 s ."}
MultiLanguageSpellData['mx'][122] = {name = "Nova de Escarcha", additional_info = "2% del maná base\n{Instante} {30 seg de reutilización}\n1 carga\n[q]Golpea a los enemigos en un radio de 12 m de ti, lo que inflige ([5.149% of Spell Power]) p. de daño de escarcha y los congela durante 6 s. Cualquier daño infligido puede interrumpir el efecto de congelación."}
MultiLanguageSpellData['mx'][126] = {name = "Ojo de Kilrogg", additional_info = "{3% del maná base} {Rango ilimitado}\nHechizo de 2 seg\n[q]Invoca un Ojo de Kilrogg y vincula tu visión a él. El ojo entra en sigilo y se mueve con rapidez, pero es muy frágil."}
