MultiLanguageSpellData['mx'][18455] = {name = "[q3]Bolsa sin fondo", additional_info = "Hechizo de 2.5 seg\nComponentes:\nMadeja de paño rúnico (8), Tela lunar (12), Fragmento luminoso grande (2), Cuero del Núcleo (2), Hilo rúnico (2)\nBotín:\nCriaturas del mundo\n\n[q3]Bolsa sin fondo\nSe liga al equiparlo\nBolsa de 18 casillas"}
MultiLanguageSpellData['mx'][18456] = {name = "[q4]Vestimentas de fe verdadera", additional_info = "Hechizo de 2 seg\nComponentes:\nMadeja de paño rúnico (12), Tela lunar (10), Orbe recto (4), Perla de oro (4), Tinte fantasmal (10), Hilo rúnico (2)\nBotín\nBalnazzar\nZona:\nStratholme\n\n[q4]Vestimentas de fe verdadera\nSe liga al recogerlo\nPecho Tela\n4 armadura\n+5 intelecto\n+5 aguante\n[q2]+ 4 Versatilidad\nDurabilidad 165 / 165\nClases: Sacerdote\n[q2]Equipar: Reduce el tiempo de reutilización de tu facultad Desvanecerse 2 s.\nNecesitas ser de nivel 24"}
MultiLanguageSpellData['mx'][18457] = {name = "[q4]Toga del archimago", additional_info = "Hechizo de 2 seg\nComponentes:\nMadeja de paño rúnico (12), Esencia de Fuego (10), Esencia de aire (10), Esencia de tierra (10), Esencia de agua (10), Hilo rúnico (2)\nBotín:\nPiromántico Pirotigma\nZona:\nCumbre de Roca Negra\n\n[q4]Toga del archimago\nSe liga al recogerlo\nPecho Tela\n4 armadura\n+5 intelecto\n+5 aguante\n[q2]Aumenta tu índice de golpe crítico + 3 p.\nDurabilidad 165 / 165\n[q2]Uso: Restaura 95 p. de maná. (5 Min Reutilización)\nNecesitas ser de nivel 24"}
MultiLanguageSpellData['mx'][18458] = {name = "[q4]Toga del Vacío", additional_info = "Hechizo de 2 seg\nComponentes:\nMadeja de paño rúnico (12), Runa demoníaca (20), Tela vil (40), Esencia de Fuego (12), Esencia de no-muerto (12), Hilo rúnico (2)\nBotín:\nMaestro oscuro Gandling\nZona:\nScholomance\n\n[q4]Toga del Vacío\nSe liga al recogerlo\nPecho Tela\n4 armadura\n+6 intelecto\n+5 aguante\nDurabilidad 165 / 165\n[q2]Uso: Sana a tu mascota 10 p. (10 Min Reutilización)\nNecesitas ser de nivel 24"}
