MultiLanguageSpellData['mx'][22717] = {name = "Corcel de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un corcel de guerra negro que se puede montar.\n[q]\"Entrenando para soportar brutales combates mano a mano en los más feroces campos de batalla.\"\nVendedora:\nTeniente Karter\nZona:\nCiudad de Ventormenta\nCosto:\n15"}
MultiLanguageSpellData['mx'][22718] = {name = "Kodo de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un kodo de guerra negro que se puede montar.\n[q]\"Criados por los maestros de establos de Kor'kron por su comportamiento agresivo e impredecible, el fuerte bramido de los kodos de guerra negros significa que pronto se derramará sangre.\"\nVendedor:\nAsaltante Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageSpellData['mx'][22719] = {name = "Zancudo de batalla negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un zancudo de batalla negro que se puede montar.\n[q]\"Un gnomo apropiadamente acelerado en batalla es algo terriblemente hermoso. -Manitas Mayor Mekkatorque\"\nVendedora:\nTeniente Karter\nZona:\nCiudad de Ventormenta\nCosto:\n15"}
MultiLanguageSpellData['mx'][22720] = {name = "Carnero de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un carnero de guerra negro que se puede montar.\n[q]\"Los enanos valoran a sus compañeros carneros por su arrojo para entrar en combate.\"\nVendedora:\nTeniente Karter\nZona:\nCiudad de Ventormenta\nCosto:\n15"}
MultiLanguageSpellData['mx'][22721] = {name = "Raptor de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un raptor de guerra negro que se puede montar.\n[q]\"Criado de la misma línea de despiadados raptores que engendraron a Ohgan y le trajeron la victoria al imperio Gurubashi.\"\nVendedor:\nAsaltante Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageSpellData['mx'][22722] = {name = "Caballo de guerra esquelético rojo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un caballo de guerra esquelético rojo que se puede montar.\n[q]\"Cuando los héroes caídos se levantan como no muertos, también lo hacen sus caballos.\"\nVendedor:\nAsaltante Bork\nZona:\nOrgrimmar\nCosto:\n15"}
MultiLanguageSpellData['mx'][22723] = {name = "Tigre de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un tigre de guerra negro que se puede montar.\n[q]\"Al igual que sus distantes primos, los tigres son conocidos por sus garras afiladas como cuchillas, increíble agilidad y sus ganas de ser rascados por detrás de las orejas.\"\nVendedora:\nTeniente Karter\nZona:\nCiudad de Ventormenta\nCosto:\n15"}
