MultiLanguageSpellData['mx'][23077] = {name = "[q3]Reflector de hielo girohielo", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nTrasto de torio (6), Transformador de veraplata (2), Zafiro azul (2), Esencia de Fuego (4), Aceite de Escarcha (2), Setelo (4)\nComponentes opcionales:\n[] (#50)\nVendedor:\nXizzer Raybuja\nZona:\nCuna del Invierno\nCosto:\n1\n20\n\n[q3]Reflector de hielo girohielo\nSe liga al equiparlo\nAbalorio\n+3 resistencia a Escarcha\n[q2]Uso: Refleja los hechizos de escarcha al taumaturgo durante 5 s. Puede fracasar cuando lo usan jugadores de nivel superior a 49. (5 Min Reutilización)\nNecesitas ser de nivel 20\nRequiereIngeniería clásica\n(260)"}
MultiLanguageSpellData['mx'][23078] = {name = "Desfibriladores goblin XL", additional_info = "Hechizo de 2 seg\nComponentes:\nTrasto de torio (2), Transformador de veraplata (2), Cableado de fusibles (2), Seda de araña Tejehierro (2), Rubí estrella (2)\nBotín:\nPlugger Aropatoso\nZona:\nProfundidades de Roca Negra\n\n[q2]Uso: Los desfibriladores a veces podrán devolver a un aliado muerto a la vida. No se pueden usar en combate. (30 Min Reutilización)\nRequiereIngeniería clásica\n(265)"}
MultiLanguageSpellData['mx'][23079] = {name = "[q2]Recombobulador sublime", additional_info = "Hechizo de 3 seg\nComponentes:\nTubo de torio (2), Transformador de veraplata , Paño rúnico (2)\nTesoro:\ntributo a Gordok\nZona:\nLa Masacre\n\n[q2]Recombobulador sublime\nAbalorio\n[q2]Uso: Restaura 9 p. de salud y maná a un objetivo amistoso e intenta disipar cualquier efecto de polimorfia sobre él. La eficacia se reduce contra efectos de polimorfia de taumaturgos de nivel 0 o superior. (5 Min Reutilización)\n10 cargas\nRequiereIngeniería clásica\n(275)"}
