MultiLanguageSpellData['mx'][27585] = {name = "[q3]Cinturón de obsidiana pesado", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana pequeño (14), Barra de torio encantado (4), Esencia de tierra (2)\nVendedor:\nVargus\nZona:\nSilithus\nel Círculo Cenarion - Amistoso\nCosto:\n5\n\n[q3]Cinturón de obsidiana pesado\nSe liga al equiparlo\nCintura Placas\n8 armadura\n+4 [Fuerza o Intelecto]Durabilidad 50 / 50\nNecesitas ser de nivel 25"}
MultiLanguageSpellData['mx'][27586] = {name = "[q4]Escudo de obsidiana dentado", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Barra de torio encantado (8), Esencia de tierra (4)\nVendedor:\nTeniente general Andorov\nZona:\nSilithus\nZona:\nRuinas de Ahn'Qiraj\nCírculo Cenarion - Venerado\nCosto:\n5\n\n[q4]Escudo de obsidiana dentado\nSe liga al equiparlo\nMano izquierda Escudo\n42 armadura\n+2 fuerza\n+6 intelecto\n+3 aguante\n[q2]+ 2 de esquivar\nDurabilidad 120 / 120\n[q2]Equipar: Al recibir un hechizo dañino, el taumaturgo de ese hechizo tiene un 5% de probabilidad de ser silenciado durante 3 s. (Probabilidad de que accione: 5%, 20s de reutilización)\nNecesitas ser de nivel 25"}
MultiLanguageSpellData['mx'][27587] = {name = "[q4]Coraza gruesa de obsidiana", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (18), Fragmento de obsidiana pequeño (40), Barra de torio encantado (12), Esencia de tierra (10), Esmeralda enorme (4)\nBotín:\nEl profeta Skeram\nZona:\nAhn'Qiraj\n\n[q4]Coraza gruesa de obsidiana\nSe liga al equiparlo\nPecho Placas\n14 armadura\n+5 [Fuerza o Intelecto]+5 aguante\nDurabilidad 165 / 165\n[q2]Equipar: Al recibir un hechizo de daño tienes el 30% de probabilidad de conseguir un hechizo escudo 6 s que absorbe 179 de ese tipo de daño. (Probabilidad de que accione: 30%, 10s de reutilización)\nNecesitas ser de nivel 25"}
MultiLanguageSpellData['mx'][27588] = {name = "[q3]Cinturón de obsidiana ligero", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana pequeño (14), Cuero encantado (4)\nVendedor:\nVargus\nZona:\nSilithus\nel Círculo Cenarion - Honorable\nCosto:\n5\n\n[q3]Cinturón de obsidiana ligero\nSe liga al equiparlo\nCintura Malla\n5 armadura\n+3 [Agilidad o Intelecto][q2]Aumenta tu índice de golpe crítico + 4 p.\nDurabilidad 50 / 50\nNecesitas ser de nivel 25"}
MultiLanguageSpellData['mx'][27589] = {name = "[q4]Garra negra del Destructor", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (8), Fragmento de obsidiana pequeño (24), Cuero encantado (8), Frasco de poder supremo\nBotín:\nMoam\nZona:\nRuinas de Ahn'Qiraj\n\n[q4]Garra negra del Destructor\nSe liga al equiparlo\nManos Malla\n5 armadura\n+2 [Agilidad o Intelecto][q2]Aumenta tu índice de golpe crítico + 3 p.\nDurabilidad 55 / 55\n[q2]Equipar: En ataques cuerpo a cuerpo o a distancia que alcancen al objetivo, obtienes 1 p. de maná y, si es posible, absorbes 1 p. de maná del objetivo.\nNecesitas ser de nivel 25"}
MultiLanguageSpellData['mx'][27590] = {name = "[q4]Guerrera de malla de obsidiana", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nFragmento de obsidiana grande (15), Fragmento de obsidiana pequeño (36), Cuero encantado (12), Piedra guardián (10), Diamante de Azeroth (4)\nVendedor:\nTeniente general Andorov\nZona:\nSilithus\nZona:\nRuinas de Ahn'Qiraj\nCírculo Cenarion - Exaltado\nCosto:\n8\n\n[q4]Túnica de placa de obsidiana\nSe liga al equiparlo\nPecho Malla\n10 armadura\n+5 [Agilidad o Intelecto][q2]Aumenta tu índice de golpe crítico + 3 p.\nDurabilidad 165 / 165\n[q2]Equipar: Se reduce el daño con hechizos recibido 0 p.\nNecesitas ser de nivel 25"}
