MultiLanguageSpellData['mx'][32388] = {name = "Abrazo de las sombras", additional_info = "[q0]Talento\n[q][ Drenar alma / Descarga de las sombras] aplica Abrazo de las sombras, lo que aumenta tu daño infligido al objetivo un [ Drenar alma : 2% / 4%] durante 16 s. Se acumula hasta [ Drenar alma : 4 / 2] veces."}
