MultiLanguageSpellData['mx'][32397] = {name = "Aplicar refuerzo para armadura", additional_info = "Hechizo de 3 seg\nRequiere Pantalones, Pecho, Pecho, [Boots], [Gloves][q]Aumenta de forma permanente 2 p. el aguante de un objeto que se lleve en el torso, las piernas, las manos o los pies. No se puede aplicar a objetos de nivel superior a 320."}
