MultiLanguageSpellData['mx'][53550] = {name = "Helada mental", additional_info = "Alcance de ataques cuerpo a cuerpo\nInstante\n[q]Golpea la mente del objetivo con frío, inflige 1 p. de daño de Escarcha modificados por el poder de ataque e interrumpe el lanzamiento de hechizos mientras que también evita que se lance ningún hechizo de esa escuela durante 4 s."}
MultiLanguageSpellData['mx'][53563] = {name = "Señal de la Luz", additional_info = "{0.5% del maná base} {Alcance de 60 m}\nInstante\n[q]Cubre a un único aliado de energía sagrada que hace que las sanaciones directas a otros miembros del grupo o la banda también sanen a ese aliado un 20% de la cantidad sanada."}
MultiLanguageSpellData['mx'][53570] = {name = "Frío hambriento", additional_info = "Alcance de 10 m\nInstante\n[q]Desata todo el poder rúnico disponible para eliminar de repente todo el calor de la tierra que rodea al caballero de la Muerte. Los enemigos que se encuentren en un radio de 10 m quedan atrapados en hielo, impidiendo que puedan realizar ninguna acción durante 1 s por cada 5 p. de poder rúnico. Se considera que los enemigos están congelados, pero cualquier daño romperá el hielo."}
MultiLanguageSpellData['mx'][53576] = {name = "Infusión de Luz", additional_info = "[q]Tus Choques sagrados tienen un 10% de probabilidad de potenciar el próximo hechizo que lances:\n\nDestello de Luz : la sanación aumenta un 150% y se convierte en un lanzamiento instantáneo.\nLuz Sagrada : la sanación aumenta un 30% y el tiempo de lanzamiento se reduce un 30%.\nSentencia : Sentencia mayor evita un 100% del daño que inflige el objetivo y genera 1 p. más de poder sagrado."}
MultiLanguageSpellData['mx'][53595] = {name = "Martillo del honrado", additional_info = "[q0]Talento\n{0.32% del maná base} {Alcance de ataques cuerpo a cuerpo}\nInstante 5 seg reutilización\n2 cargas\n[q]Golpea fuertemente al objetivo actual y le inflige ([97.5% of Attack Power])% p. de daño físico. [ Consagración : Martillo del honrado también lanza una oleada de luz que golpea al resto de los objetivos en un radio de 8 m y les inflige ([13.56% of Attack Power])% p. de daño sagrado ] [ Mientras estés parado sobre tu Consagración, Martillo del honrado también lanza una oleada de luz que golpea al resto de los objetivos en un radio de 8 m y les inflige ([13.56% of Attack Power])% p. de daño sagrado ]\nGenera 1 p. de poder sagrado."}
