MultiLanguageSpellData['mx'][56465] = {name = "[q3]Gafas de nieve mecanizadas", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de saronita (8), Cuero boreal (2), Sombra eterna\nComponentes opcionales:\n[] (#47)\nInstructor de profesión:\nIngeniería de Rasganorte (45)\nCosto:\n1\n75\n\n[q3]Gafas de nieve mecanizadas\nSe liga al equiparlo\nCabeza Tela\n3 armadura\n+4 intelecto\n+6 aguante\nDurabilidad 85 / 85\n[q2]Equipar: Protegido del frío. Tu resistencia a la Escarcha aumenta 6 p.\nNecesitas ser de nivel 24\nRequiereIngeniería de Rasganorte\n(1)"}
MultiLanguageSpellData['mx'][56466] = {name = "[q3]Propulsor sónico", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nTubo de acero gélido reforzado (2), Condensador sobrecargado (4), Puñado de tornillos de cobalto (2)\nComponentes opcionales:\n[] (#31)\nInstructor de profesión:\nIngeniería de Rasganorte (45)\nCosto:\n1\n75\n\n[q3]Propulsor sónico\nSe liga al equiparlo\nAbalorio\n+5 aguante\n[q2]Equipar: El ruido que produce el combate cuerpo a cuerpo a veces provoca Conciencia sónica, que aumenta tu poder de ataque 14 p. durante 10 s. Este efecto solo puede darse una vez cada minuto. (Probabilidad de que accione: 35%, 50s de reutilización)\nNecesitas ser de nivel 24\nRequiereIngeniería de Rasganorte\n(15)"}
MultiLanguageSpellData['mx'][56467] = {name = "[q3]Máquina de ruido", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nTubo de acero gélido reforzado (2), Condensador sobrecargado (2), Puñado de tornillos de cobalto (8)\nComponentes opcionales:\n[] (#31)\nInstructor de profesión:\nIngeniería de Rasganorte (45)\nCosto:\n1\n75\n\n[q3]Máquina de ruido\nSe liga al equiparlo\nAbalorio\n+4 intelecto\n[q2]Equipar: Los ataques cuerpo a cuerpo contra ti tienen la posibilidad de invocar un Escudo sónico que absorbe 6 p. de daño. Este efecto solo puede tener lugar una vez por minuto. (Probabilidad de que accione: 50%, 50s de reutilización)\nNecesitas ser de nivel 24\nRequiereIngeniería de Rasganorte\n(15)"}
MultiLanguageSpellData['mx'][56468] = {name = "Caja de bombas", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de saronita (5), Activador de explosivo volátil\nInstructor de profesión:\nIngeniería de Rasganorte (30)\nCosto:\n1\n15\n\n[q]\"Contiene bombas de saronita. Muchas.\"\n[q2]<Click derecho para abrir>"}
MultiLanguageSpellData['mx'][56469] = {name = "[q3]Generador de relámpagos gnómico", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de titanio (2), Barra de saronita (8), Agua eterna (2), Aire eterno (2)\nComponentes opcionales:\n[] (#31)\nInstructor de profesión:\nIngeniería de Rasganorte (50)\nCosto:\n2\n\n[q3]Generador de relámpagos gnómico\nSe liga al recogerlo\nAbalorio\n[q2]Aumenta tu índice de golpe crítico + 7 p.\n[q2]Uso: Genera una descarga de relámpagos que golpea a un enemigo y le inflige 87 p. de daño de Naturaleza. Este aparato está construido entero con metal... (1 Min Reutilización)\nNecesitas ser de nivel 24\nRequiereIngeniería de Rasganorte\n(50)\n[q]\"¡Es seguro!\""}
MultiLanguageSpellData['mx'][56470] = {name = "[q3]Mira solar", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero\nComponentes:\nTubo de acero gélido reforzado , Cristal de sol , Brillo del otoño\nInstructor de profesión:\nIngeniería de Rasganorte (50)\nCosto:\n2\n\n[q3]Mira solar\n[q2]Uso: Añade una mira permanente a un arco o un arma de fuego y aumenta 16 p. tu celeridad a distancia.\n\n Si añades esta mira a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 27"}
