MultiLanguageSpellData['mx'][59567] = {name = "Draco azur", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un draco azur que se puede montar. Es una montura voladora.\n[q]\"Siempre háblale cortésmente a un dragón enfurecido.\"\nBotín:\nObsequio de Alexstrasza\nUbicación:\nOjo de la Eternidad"}
