MultiLanguageSpellData['mx'][59570] = {name = "Draco rojo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un draco rojo que se puede montar. Es una montura voladora.\n[q]\"Nunca escuches las palabras de un juglar. Un dragón nunca le haría daño a nadie, a menos de que intenten hacerle daño primero.\"\nVendedor:\nCielstrasza\nZona:\nCementerio de Dragones\nEl Acuerdo del Reposo del Dragón - Exaltado\nCosto:\n2000"}
MultiLanguageSpellData['mx'][59571] = {name = "Draco Crepuscular", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un draco Crepuscular que se puede montar. Es una montura voladora.\n[q]\"Pero la regla más importante, la que no debes olvidar, no importa cuánto llore, no importa cuánto suplique, nunca le des de comer después de medianoche.\"\nBotín:\nSartharion\nUbicación:\nEl Sagrario Obsidiana"}
