MultiLanguageSpellData['mx'][59785] = {name = "Mamut de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un mamut de guerra negro que se puede montar.\n[q]\"Generalmente bestias tranquilas, estos inteligentes animales forman un fuerte vínculo con sus dueños, lo que los hace leales y audaces al luchar.\"\nVendedor:\nCaballero Dameron\nZona:\nConquista del Invierno\nCosto:\n15"}
MultiLanguageSpellData['mx'][59787] = {name = "Abluciones del Oráculo", additional_info = "[q]Restaura maná, ira, energía, enfoque o poder rúnico cuando matas a un objetivo que otorga honor o experiencia."}
MultiLanguageSpellData['mx'][59788] = {name = "Mamut de guerra negro", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un mamut de guerra negro que se puede montar.\n[q]\"Firme y sereno, estos mamuts de pelaje oscuro son valorados por su personalidad tranquila a la hora de luchar.\"\nVendedor:\nGuardia de piedra Mutaha\nZona:\nConquista del Invierno\nCosto:\n15"}
