MultiLanguageSpellData['mx'][63635] = {name = "Raptor Lanza Negra", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un raptor Lanza Negra que se puede montar.\n[q]\"Esta raza de raptor la cultivaron originalmente los drakkari, pero desde entonces fue adoptada por la tribu Lanza Negra en Rasganorte.\"\nVendedora:\nSamamba\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63636] = {name = "Carnero de Forjaz", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un carnero de Forjaz que se puede montar.\n[q]\"Verificador Martillo Salvaje asegura que esta raza en específico fue la primera de su tipo de carneros domesticada por los enanos cuando se establecieron en Dun Morogh.\"\nVendedor:\nDerrick Barba Berrenda\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63637] = {name = "Sable de la noche darnassiano", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un sable de la noche darnassiano que se puede montar.\n[q]\"Cuando la montura de un elfo de la noche muere, es costumbre que el jinete guarde uno de sus colmillos como amuleto de rememoración.\"\nVendedor:\nRook Puñohalcón\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63638] = {name = "Mecazancudo de Gnomeregan", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un mecazancudo de Gnomeregan que se puede montar.\n[q]\"Cuando absoluta y positivamente tienes que estar ahí ahora mismo. -Rillie Ejeloco\"\nVendedora:\nRillie Ejeloco\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63639] = {name = "Elekk de El Exodar", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un elekk de El Exodar que se puede montar.\n[q]\"Los elekk de El Exodar son elekk consagrados por los O'ros, naaru que viajaron de Draenor a Azeroth con Velen y sus seguidores.\"\nVendedora:\nIrisee\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63640] = {name = "Lobo de Orgrimmar", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un lobo de Orgrimmar que se puede montar.\n[q]\"Por un breve periodo de tiempo, muchos orcos se declaraban a sí mismos como \"tan hambrientos como un lobo de Orgrimmar\". Algunos elfos de sangre aún usan esa frase irónicamente.\"\nVendedora:\nFreka Hacha de Sangre\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63641] = {name = "Kodo de Cima del Trueno", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un kodo de Cima del Trueno que se puede montar.\n[q]\"Un miembro alfa de la manada, este kodo es un gran ejemplo de las poderosas criaturas que retumban a través de Mulgore.\"\nVendedor:\nDoru Tronacuerno\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63642] = {name = "Halcón zancudo de Lunargenta", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un halcón zancudo de Lunargenta que se puede montar.\n[q]\"Así que voy y digo, tengo ganas de comer pollo esta noche. Luego, estoy tirado y esa cosa intenta ver a que saben mis ojos. -Bozzle Cargarrayo\"\nVendedor:\nTrellis Sol de Mañana\nZona:\nCorona de Hielo\nCosto:\n100"}
MultiLanguageSpellData['mx'][63643] = {name = "Caballo de guerra Renegado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un caballo de guerra Renegado que se puede montar.\n[q]\"Cuando los héroes caídos se levantan como no muertos, también lo hacen sus caballos.\"\nVendedora:\nEliza Killian\nZona:\nCorona de Hielo\nCosto:\n100"}
