MultiLanguageSpellData['mx'][65637] = {name = "Gran elekk rojo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un gran elekk rojo que se puede montar.\n[q]\"Nunca vistos en Nagrand, los primeros cachorros de elekk rojo nacieron en Azeroth tras la llegada de Exodar. Algunos criadores tienen la teoría de que su color único es de alguna manera provocado por la misma radiación que se propagó por la Isla Bruma de Sangre.\"\nVendedor:\nIrisee\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65638] = {name = "Sable de la luna presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un sable de la luna presto que se puede montar.\n[q]\"Muchos elfos de la noche veneran a estas orgullosas monturas porque su deslumbrante pelaje simboliza a la diosa de la luna, Elune.\"\nVendedor:\nRook Puñohalcón\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65639] = {name = "Halcón zancudo rojo presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un halcón zancudo rojo presto que se puede montar.\n[q]\"¿Cómo que si es teñido? Ah, el pájaro. Le retocamos el color rojo un poco. -Trellis Sol de Mañana\"\nVendedor:\nTrellis Sol de Mañana\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65640] = {name = "Corcel gris presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un corcel gris presto que se puede montar.\n[q]\"Un veterano de algunas de las batallas más duras luchadas por la Cruzada Argenta.\"\nVendedor:\nCabo Arthur Flew\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65641] = {name = "Gran kodo dorado", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un gran kodo dorado que se puede montar.\n[q]\"Un miembro alfa de la manada, este kodo es un gran ejemplo de las poderosas criaturas que retumban a través de Los Baldíos del Sur.\"\nVendedor:\nDoru Tronacuerno\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65642] = {name = "Turbozancudo", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un turbozancudo que se puede montar.\n[q]\"El espejo no es para que puedas mirar atrás, sino para que tus enemigos puedan ver algo más que tus tubos de escape. -Rillie Ejeloco\"\nVendedor:\nRillie Ejeloco\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65643] = {name = "Carnero violeta presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un carnero violeta presto que se puede montar.\n[q]\"El cráneo grueso y huesudo del carnero de Barak Tor'ol y sus masivos cuernos lo hacen la montura ideal para arremeter contra grupos de enemigos acorazados.\"\nVendedor:\nDerrick Barba Berrenda\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65644] = {name = "Raptor morado presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un raptor morado presto que se puede montar.\n[q]\"Viejos aliados de los trols, estos cazadores de la jungla crean un vínculo especial con sus amos. Se convierten en monturas, guardianes y amigos.\"\nVendedor:\nSamamba\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65645] = {name = "Caballo de guerra esquelético blanco", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un caballo de guerra esquelético blanco que se puede montar.\n[q]\"Cuando los héroes caídos se levantan como no muertos, también lo hacen sus caballos.\"\nVendedor:\nEliza Killian\nZona:\nCorona de Hielo\nCosto:\n500"}
MultiLanguageSpellData['mx'][65646] = {name = "Lobo burdeos presto", additional_info = "Hechizo de 1.5 seg\n[q]Invoca y retira a un lobo burdeos presto que se puede montar.\n[q]\"Uno no domestica a los lobos de la Horda, se hace amigo de ellos.\"\nVendedor:\nFreka Hacha de Sangre\nZona:\nCorona de Hielo\nCosto:\n500"}
