MultiLanguageSpellData['mx'][65790] = {name = "Contrahechizo", additional_info = "{9% del maná base} {Alcance de 30 m}\n{Instante} {24 seg de reutilización}\n[q]Contrarresta el lanzamiento de hechizos del enemigo, evitando que lance hechizos de esa escuela de magia durante 8 s. Genera una gran cantidad de amenaza."}
MultiLanguageSpellData['mx'][65791] = {name = "Explosión Arcana", additional_info = "{8% del maná base} {Alcance de 30 m}\nHechizo de 2.5 seg\n[q]Golpea al objetivo con energía, lo que inflige 2266 p. de daño Arcano. Cada vez que lances el hechizo Explosión Arcana, el daño de todos tus hechizos Arcanos aumentará un 60% y el coste de maná de Explosión Arcana aumentará un 90%. El efecto se acumula hasta 4 veces y dura hasta que se cancela o hasta que se lance un hechizo que inflija daño Arcano, excepto Explosión Arcana."}
MultiLanguageSpellData['mx'][65792] = {name = "Nova de Escarcha", additional_info = "8% del maná base\n{Instante} {25 seg de reutilización}\n[q]Golpea a los enemigos situados cerca del taumaturgo, lo que inflige ([19.3% of Spell Power]) p. de daño de Escarcha y los congela durante un máximo de 8 s. Cualquier daño infligido puede interrumpir su efecto."}
MultiLanguageSpellData['mx'][65793] = {name = "Traslación", additional_info = "21% del maná base\n{Instante} {15 seg de reutilización}\n[q]Teletransporta al taumaturgo 20 m hacia delante salvo si hay algún obstáculo y lo libera de sus ataduras y del aturdimiento."}
