MultiLanguageSpellData['mx'][65798] = {name = "Lluvia de estrellas", additional_info = "Canalizado (Hechizo de 8 seg) 30 seg de reutilización\n[q]Invoca un aluvión de estrellas que caen del cielo sobre todos los objetivos en un radio de 30 m del taumaturgo e infligen, cada una, 55 p. de daño Arcano a todos los enemigos en un radio de 5 m del objetivo enemigo. Dura 8 s."}
MultiLanguageSpellData['mx'][65799] = {name = "Tromba Arcana", additional_info = "{18% del maná base} {Alcance de 30 m}\n{Instante} {3 seg de reutilización}\n[q]Lanza contra el objetivo enemigo varios misiles que le infligen 1846 p. de daño Arcano."}
MultiLanguageSpellData['mx'][65800] = {name = "Deflagración Arcana", additional_info = "22% del maná base\nInstante\n[q]Provoca una explosión de magia Arcana alrededor del taumaturgo, lo que inflige 24 p. de daño Arcano a todos los objetivos en un radio de 10 m."}
MultiLanguageSpellData['mx'][65801] = {name = "Polimorfia", additional_info = "{7% del maná base} {Alcance de 30 m}\nHechizo de 1.5 seg 15 seg de reutilización\n[q]Transforma al enemigo en oveja y le obliga a deambular durante 10 s. Mientras deambula, la oveja no puede atacar ni lanzar hechizos. Si recibe daño volverá a su forma normal. Solo se puede aplicar polimorfia a 1 objetivo al mismo tiempo. Solo funciona con bestias, humanoides y alimañas."}
MultiLanguageSpellData['mx'][65802] = {name = "Bloque de hielo", additional_info = "15 maná\n{Instante} {5 min de reutilización}\n[q]Te envuelve en un bloque de hielo que te protege de todos los ataques físicos y hechizos durante 5 s, pero durante ese tiempo no puedes moverte, atacar ni lanzar hechizos. También provoca Hipotermia, que te impide volver a lanzar Bloque de hielo durante 30 s."}
