MultiLanguageSpellData['mx'][79954] = {name = "Armadura vil", additional_info = "28% del maná base\nInstante\n[q]Rodea al taumaturgo con energía vil, lo que aumenta el poder con hechizos un 10%. Además, recuperas un 2% de tu salud máxima cada 5 s. Solo se puede tener un hechizo de armadura activo a la vez. Dura 30 min."}
MultiLanguageSpellData['mx'][79955] = {name = "Lluvia de Fuego", additional_info = "35 maná Alcance de 30 m\nCanalizado (Hechizo de 9 seg)\n[q]Invoca una lluvia de arrabio que quema a todos los enemigos del área seleccionada e inflige daño de Fuego cada 3 s durante 9 s."}
MultiLanguageSpellData['mx'][79956] = {name = "Maldición de los Elementos", additional_info = "{10% del maná base} {Alcance de 30 m}\nInstante\n[q]Maldice al objetivo durante 30 s, lo que reduce su resistencia a lo Arcano, al Fuego, a la Escarcha, a la Naturaleza y a las Sombras 125 p. y aumenta el daño mágico que recibe un 8%. Un taumaturgo solo puede tener una maldición activa a la vez sobre un mismo objetivo."}
MultiLanguageSpellData['mx'][79957] = {name = "Enlace de alma", additional_info = "{16% del maná base} {Alcance de 100 m}\nInstante\n[q]Cuando está activo, reduce todo el daño que recibe el taumaturgo un 20% y lo copia al diablillo, abisario, súcubo, manáfago, guardia vil o demonio esclavizado. Ese daño no se puede evitar. Dura el tiempo que demonio esté activo y controlado."}
MultiLanguageSpellData['mx'][79958] = {name = "Invocar guardia vil", additional_info = "80% del maná base\nInstante\n[q]Invoca a un guardia vil a las órdenes del taumaturgo."}
