MultiLanguageSpellData['mx'][79966] = {name = "Consagración", additional_info = "22% del maná base\nInstante\n[q]Consagra el suelo que el taumaturgo tiene bajo sus pies, lo que inflige daño Sagrado durante 8 s a los enemigos que lo pisen."}
