MultiLanguageSpellData['mx'][84403] = {name = "Puñado de tornillos de obsidium", additional_info = "Hechizo de 1.5 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de obsidium (2)\nProfesión:\nIngeniería (1)Instructor de profesión:\nIngeniería de Cataclysm (1)\nCosto:\n10\n\n(3)\nMaterial de profesión"}
MultiLanguageSpellData['mx'][84406] = {name = "Auténticas gafas de ingeniero Jr.", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nBarra de obsidium (8), Grosularia (2), Cuero salvaje (2)\nInstructor de profesión:\nIngeniería de Cataclysm (1)\nCosto:\n10\n\nCosmético\nSe liga al equiparlo\nCabeza Cosmético\nDurabilidad 40 / 40\n[q2]Equipar: Te hace parecer más dotado y atractivo.\n[q2]Uso: Añade esta apariencia a tu colección de tropa."}
MultiLanguageSpellData['mx'][84408] = {name = "[q3]Buscamenazas R19", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de obsidium (6), Puñado de tornillos de obsidium (6), Alicita (2)\nInstructor de profesión:\nIngeniería de Cataclysm (1)\nCosto:\n10\n\n[q3]Buscamenazas R19\n[q2]Uso: Añade una mira permanente a un arco o un arma de fuego y aumenta 17 p. su golpe de largo alcance.\n\n Si añades esta mira a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 30"}
MultiLanguageSpellData['mx'][84409] = {name = "Paquexplosivo de seforio volátil", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nPuñado de tornillos de obsidium , Éter electrificado (2)\nInstructor de profesión:\nIngeniería de Cataclysm (5)\nCosto:\n15\n\n[q2]Uso: Revienta puertas cerradas y cofres que requieren una habilidad en Forzar cerraduras de 35 p. o menos.\nRequiereIngeniería de Cataclysm\n(1)"}
MultiLanguageSpellData['mx'][84410] = {name = "[q3]Equipo de retirada de seguro", additional_info = "Hechizo de 2 seg\nHerramientas: Microajustador giromático\nComponentes:\nBarra de obsidium (10), Puñado de tornillos de obsidium (10)\nInstructor de profesión:\nIngeniería de Cataclysm (1)\nCosto:\n10\n\n[q3]Equipo de retirada de seguro\n[q2]Uso: Elimina el mecanismo de seguridad de un arco o arma de fuego, lo que aumenta 17 p. su celeridad a distancia.\n\n Al usar este equipo, el arco o arma de fuego se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 30"}
MultiLanguageSpellData['mx'][84411] = {name = "[q3]Pistola de descarga de gran potencia", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de obsidium (10), Puñado de tornillos de obsidium (8), Éter electrificado (4)\nInstructor de profesión:\nIngeniería de Cataclysm (15)\nCosto:\n50\n\n[q3]Pistola de descarga de gran potencia\nSe liga al usarlo\n[q2]Uso: Dispara varios tornillos cargados a un enemigo que infligen 108 p. de daño e interrumpen brevemente el lanzamiento. Consume un puñado de tornillos de obsidium cada vez que se dispara. (2 Min Reutilización)\nNecesitas ser de nivel 29\nRequiereIngeniería de Cataclysm\n(1)\n[q]\"Casi tan complicada de hacer que funcione como de fabricarla.\""}
MultiLanguageSpellData['mx'][84412] = {name = "[q2]Destruyemundos personal", additional_info = "Hechizo de 3.5 seg\nHerramientas: Pistola de descarga de gran potencia , Martillo de herrero\nComponentes:\nBarra de obsidium (10), Puñado de tornillos de obsidium (8), Éter electrificado (8)\nInstructor de profesión:\nIngeniería de Cataclysm (25)\nCosto:\n1\n\n[q2]Destruyemundos personal\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del ratón para invocar y retirar a tu destruyemundos personal.\n1 - 80 ( 80)"}
MultiLanguageSpellData['mx'][84413] = {name = "[q2]Compañero mecánico sin armas", additional_info = "Hechizo de 3.5 seg\nHerramientas: Pistola de descarga de gran potencia , Llave de tuerca arcoluz\nComponentes:\nBarra de obsidium (12), Puñado de tornillos de obsidium (4), Éter electrificado (8), Jaspe (2)\nInstructor de profesión:\nIngeniería de Cataclysm (25)\nCosto:\n1\n\n[q2]Compañero mecánico sin armas\n[q2]Uso: Te enseña a invocar este compañero.\n[q2]Haz clic con el botón derecho del ratón para invocar y retirar a tu compañero mecánico sin armas.\n1 - 80 ( 80)"}
MultiLanguageSpellData['mx'][84415] = {name = "[q3]Caja de aparejos Maestro del Cebo", additional_info = "Hechizo de 3.5 seg\nHerramientas: Martillo de herrero , Pistola de descarga de gran potencia\nComponentes:\nBarra de elementium (20), Puñado de tornillos de obsidium (4)\nInstructor de profesión:\nIngeniería de Cataclysm (25)\nCosto:\n1\n\n[q3]Caja de aparejos Maestro del Cebo\nSe liga al equiparlo\nCaja de aparejos de 36 casillas"}
MultiLanguageSpellData['mx'][84416] = {name = "[q3]Caja de herramientas de elementium", additional_info = "Hechizo de 3.5 seg\nHerramientas: Martillo de herrero\nComponentes:\nBarra de elementium (15), Tierra volátil (12)\nInstructor de profesión:\nIngeniería de Cataclysm (25)\nCosto:\n1\n\n[q3]Caja de herramientas de elementium\nSe liga al equiparlo\nBolsa de ingeniería de 36 casillas\n[q]\"Posiblemente la mejor caja de herramientas jamás hecha, adornada con incrustaciones de oro.\""}
MultiLanguageSpellData['mx'][84417] = {name = "[q3]Truenopalo volátil", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nÉter electrificado (2), Barra de elementium endurecido (5), Fuego volátil (6)\nComponentes opcionales:\n[] (#47)\nInstructor de profesión:\nIngeniería de Cataclysm (45)\nCosto:\n1\n75\n\n[q3]Truenopalo volátil\nSe liga al equiparlo\nA distancia Arma de fuego\n6 - 12 p. de daño Velocidad 3.00\n(3.0 p. de daño por segundo)\n+4 agilidad\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de maestría + 4 p.\nDurabilidad 80 / 80\nNecesitas ser de nivel 31"}
MultiLanguageSpellData['mx'][84418] = {name = "[q3]Dragonizo de elementium", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Pistola de descarga de gran potencia\nComponentes:\nPuñado de tornillos de obsidium (2), Éter electrificado (8), Barra de elementium (16), Paño de seda de ascuas (20)\nComponentes opcionales:\n[] (#47)\nInstructor de profesión:\nIngeniería de Cataclysm (25)\nCosto:\n1\n\n[q3]Dragonizo de elementium\nSe liga al equiparlo\nÚnico-EquipadoAbalorio\n[q2]Aumenta tu índice de maestría + 6 p.\n[q2]Uso: Activa tu dragonizo de elementium para que luche por ti durante 1 min. (5 Min Reutilización)\nNecesitas ser de nivel 30\nRequiereIngeniería de Cataclysm\n(25)"}
