MultiLanguageSpellData['mx'][84420] = {name = "[q3]Taladro de garganta bien afinado", additional_info = "Hechizo de 3 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de obsidium (4), Éter electrificado (2), Barra de elementium endurecido (5)\nComponentes opcionales:\n[] (#47)\nInstructor de profesión:\nIngeniería de Cataclysm (40)\nCosto:\n1\n50\n\n[q3]Taladro de garganta bien afinado\nSe liga al equiparlo\nA distancia Ballesta\n7 - 11 p. de daño Velocidad 3.00\n(3.0 p. de daño por segundo)\n+4 agilidad\n+6 aguante\n[q2]Aumenta tu índice de golpe crítico + 4 p.\n[q2]Aumenta tu índice de celeridad + 4 p.\nDurabilidad 80 / 80\nNecesitas ser de nivel 31"}
MultiLanguageSpellData['mx'][84421] = {name = "[q3]Despojador a distancia", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Llave de tuerca arcoluz\nComponentes:\nBarra de elementium endurecido (5), Éter electrificado (5)\nInstructor de profesión:\nIngeniería de Cataclysm (40)\nCosto:\n1\n50\n\n[q3]Despojador a distancia\nSe liga al usarlo\nJuguete\n[q2]Uso: Obtiene el botín de un cadáver cercano. (3 Seg Reutilización)\nRequiereIngeniería de Cataclysm\n(70)"}
MultiLanguageSpellData['mx'][84424] = {name = "Campo de invisibilidad", additional_info = "Hechizo de 2 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nKit de manitas\n[q]Añade permanentemente miles de espejos pequeños a tu cinturón, lo que te permite intentar volverte invisible mientras no estás en combate. (3 min de tiempo de reutilización)\nProfesión:\nIngeniería de Cataclysm (1)\nDescubrimiento:\nRecetas de ingeniería de Cataclysm"}
MultiLanguageSpellData['mx'][84425] = {name = "Asesino de cartón", additional_info = "Hechizo de 2 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nKit de manitas\n[q]Añade de forma permanente un pequeño dispositivo a tu cinturón, lo que te permite crear un asesino de cartón al que tus enemigos atacarán. (5 min de tiempo de reutilización)\nProfesión:\nIngeniería de Cataclysm (1)\nDescubrimiento:\nRecetas de ingeniería de Cataclysm"}
