MultiLanguageSpellData['mx'][84427] = {name = "Escudo de plasma con toma de tierra", additional_info = "Hechizo de 2 seg\nRequiere Cinturón\nHerramientas: Llave de tuerca arcoluz\nComponentes:\nKit de manitas\n[q]Añade de forma permanente unos generadores de plasma con toma de tierra a tu cinturón, lo que te permite activar un poderoso escudo que absorbe de daño. (5 min de tiempo de reutilización)\nProfesión:\nIngeniería de Cataclysm (1)\nDescubrimiento:\nRecetas de ingeniería de Cataclysm"}
MultiLanguageSpellData['mx'][84428] = {name = "[q3]Mira de rayos X gnómica", additional_info = "Hechizo de 2 seg\nHerramientas: Martillo de herrero , Microajustador giromático\nComponentes:\nBarra de elementium endurecido (2), Esmeralda onírica (2)\nInstructor de profesión:\nIngeniería de Cataclysm (65)\nCosto:\n2\n75\n\n[q3]Mira de rayos X gnómica\n[q2]Uso: Añade una mira permanente a un arco o un arma de fuego, lo que hace que tu poder de ataque a distancia a veces aumente 76 p. durante 10 s al infligir daño con ataques a distancia.\n\n Si añades esta mira a un arma de ataque a distancia, el arma se ligará al alma. No se puede aplicar a objetos de nivel superior a 320.\nNecesitas ser de nivel 30"}
MultiLanguageSpellData['mx'][84429] = {name = "Barbacoa goblin", additional_info = "Hechizo de 2 seg\nHerramientas: Pistola de descarga de gran potencia , Llave de tuerca arcoluz\nComponentes:\nBarra de elementium (2), Carne fortalecida (2), Filete de lavesco (2)\nInstructor de profesión:\nIngeniería de Cataclysm (55)\nCosto:\n2\n25\n\n[q2]Uso: ¡Saca una barbacoa para alimentar a todo tu grupo o banda!\n\n Restaura 6510 p. de salud y ( 1118 / 5 * 30) p. de maná durante 30 s. Si pasas al menos 10 s comiendo estarás bien alimentado y ganarás 9 p. de aguante y 9 p. de otra estadística útil durante 1 h.\nNecesitas ser de nivel 30\nRequiereCocina de Cataclysm\n(25)"}
MultiLanguageSpellData['mx'][84430] = {name = "Cebo giratorio tratado con calor", additional_info = "Hechizo de 2 seg\nHerramientas: Llave de tuerca arcoluz , Microajustador giromático\nComponentes:\nPuñado de tornillos de obsidium , Barra de elementium (4), Fuego volátil\nInstructor de profesión:\nIngeniería de Cataclysm (60)\nCosto:\n2\n50\n\n(2)\n[q2]Uso: Cuando lo aplicas a tu caña de pescar, aumenta 10 p. la habilidad de pesca durante 15 minutos.\nRequierePesca de Cataclysm\n(1)\n[q]\"¡Funciona hasta en la lava!\""}
